CREATE DATABASE IF NOT EXISTS jazeera_hospital CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE jazeera_hospital;
CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(160) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, role ENUM('Super Admin','Admin','Doctor','Nurse','Receptionist','Pharmacist','Demo Viewer') NOT NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, session_version INT NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS departments (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, description TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS patients (id INT AUTO_INCREMENT PRIMARY KEY, patient_code VARCHAR(30) NOT NULL UNIQUE, full_name VARCHAR(150) NOT NULL, gender ENUM('Male','Female','Other') NOT NULL, dob DATE NULL, phone VARCHAR(30), address VARCHAR(255), blood_group VARCHAR(5), emergency_contact VARCHAR(100), medical_history TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS doctors (id INT AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(150) NOT NULL, specialization VARCHAR(120), department_id INT NULL, phone VARCHAR(30), email VARCHAR(160), availability VARCHAR(150), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (department_id) REFERENCES departments(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS appointments (id INT AUTO_INCREMENT PRIMARY KEY, patient_id INT NOT NULL, doctor_id INT NOT NULL, appointment_at DATETIME NOT NULL, reason VARCHAR(255), status ENUM('Pending','Confirmed','Completed','Cancelled') DEFAULT 'Pending', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(patient_id) REFERENCES patients(id), FOREIGN KEY(doctor_id) REFERENCES doctors(id));
CREATE TABLE IF NOT EXISTS admissions (id INT AUTO_INCREMENT PRIMARY KEY, patient_id INT NOT NULL, ward VARCHAR(100), bed_number VARCHAR(30), admitted_on DATE NOT NULL, discharged_on DATE NULL, status ENUM('Admitted','Discharged') DEFAULT 'Admitted', FOREIGN KEY(patient_id) REFERENCES patients(id));
CREATE TABLE IF NOT EXISTS staff (id INT AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(150) NOT NULL, position VARCHAR(100), phone VARCHAR(30), email VARCHAR(160), salary DECIMAL(12,2) DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS lab_tests (id INT AUTO_INCREMENT PRIMARY KEY, patient_id INT NOT NULL, test_name VARCHAR(150) NOT NULL, result TEXT, test_date DATE NOT NULL, status ENUM('Requested','Processing','Completed') DEFAULT 'Requested', FOREIGN KEY(patient_id) REFERENCES patients(id));
CREATE TABLE IF NOT EXISTS medicines (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL, category VARCHAR(100), quantity INT NOT NULL DEFAULT 0, unit_price DECIMAL(12,2) NOT NULL DEFAULT 0, expiry_date DATE NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS invoices (id INT AUTO_INCREMENT PRIMARY KEY, patient_id INT NOT NULL, description VARCHAR(255) NOT NULL, amount DECIMAL(12,2) NOT NULL, paid_amount DECIMAL(12,2) NOT NULL DEFAULT 0, payment_method ENUM('Cash','Mobile Money','Card') NULL, status ENUM('Unpaid','Partial','Paid') DEFAULT 'Unpaid', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(patient_id) REFERENCES patients(id));
INSERT IGNORE INTO departments(name,description) VALUES ('Emergency','Emergency and urgent care'),('Cardiology','Heart care'),('Pediatrics','Children care'),('Surgery','Surgical services'),('Maternity','Maternity services'),('Laboratory','Diagnostic laboratory'),('Radiology','Imaging services'),('Pharmacy','Medicine services'),('OPD','Outpatient department');
